#ifndef PIME_UI_COLORS_H
#define PIME_UI_COLORS_H

#include <nlohmann/json.hpp>

namespace PIME {

// Read one 24-bit color from the customizeUI object. Returns `fallback`
// (0 = follow the system palette) when the key is absent, not an integer,
// or outside 0..0xFFFFFF.
inline unsigned int uiColorValue(const nlohmann::json& ui, const char* name, unsigned int fallback) {
	if (!ui.is_object()) {
		return fallback;
	}
	const auto it = ui.find(name);
	if (it == ui.end() || !it->is_number_integer()) {
		return fallback;
	}
	const int value = it->get<int>();
	if (value < 0 || value > 0xFFFFFF) {
		return fallback;
	}
	return static_cast<unsigned int>(value);
}

} // namespace PIME

#endif // PIME_UI_COLORS_H
